#Region @DOC
# Description:
# This process creates a view that can be used for exporting, copying or zeroing out numbers.

# Use case: Intended for development/prototyping or production.
# 1/ Create a view to zero out data.
# 2/ Create a view to use as a source for exporting or copying.

# Note:
# Naturally, a valid cube name (pCube) is mandatory otherwise the process will abort.
# The pFilter parameter contains the dimenson and elements to be used for filtering:
# - The format of the pFilter parameter is as follows delimiters of :, & and +: Dim1: Elem1 + Elem2 & Dim2: Elem3 + Elem4.
# - The dimension parameters do not need to be given in the index order of dimensions in the cube.
# - The dimension name is specified as the first member of the delimited string of elements.
# - If consols are skipped the N level children of any consolidated filter elements will be used.
# - Spaces are ignored so use them to make your filter more readable.
# - pTemp: This parameter will control whether to make the view temporary (value 1) or if the
#   view will be permanently retained (value 0).
#EndRegion @DOC

### Global Variables
pJson = IF( pJson @= '', '{}', pJson );
StringGlobalVariable(  'sBedrockReturnValue' );
NumericGlobalVariable( 'nBedrockReturnValue' );

### Constants ###
cThisProcName   = GetProcessName();
cUserName       = TM1User();
cTimeStamp      = TimSt( Now, '\Y\m\d\h\i\s' );
cRandomInt      = NumberToString( INT( RAND( ) * 1000000000 ));
cTemp           = cThisProcName |'_'| cTimeStamp |'_'| cRandomInt;
sMessages       = '{"Process": "'|cThisProcName|'", "User": "'|cUsername|'", "Info": ["Process: '''|cThisProcName|''' run by User: '''|cUsername|'''."], "Error": []}';

#################################################################################################
#Region - Process Parameters

pJson = IF( JsonType( pJson ) @<> 'object', '{}', pJson );
sMessages = '{"Process": "'|GetProcessName()|'", "User": "'|TM1User()|'", "Info": ["Process: '''|GetProcessName()|''' run by User: '''|TM1User()|'''."], "Error": []}';
pDefaultParameters = '{
  "pProcess":             null,
  "pProcessParameters":   "",
  "pSourceDatabaseName":  null,
  "pTargetDatabaseName":  null,
  "pLogOutput":           0,
  "pStrictErrorHandling": 0
}';

pPassedParameters = '{
  "pProcess":             '|StringToJson  ( pProcess             )|',
  "pProcessParameters":   '|StringToJson  ( pProcessParameters   )|',
  "pSourceDatabaseName":  '|StringToJson  ( pSourceDatabaseName  )|',
  "pTargetDatabaseName":  '|StringToJson  ( pTargetDatabaseName  )|',
  "pLogOutput":           '|NumberToString( pLogOutput           )|',
  "pStrictErrorHandling": '|NumberToString( pStrictErrorHandling )|'
}';

pJson = JsonMergePatch( pPassedParameters, pJson );
# String Parameters
pProcess             =                 JsonToString( pJson, '/pProcess'             );
pProcessParameters   =                 JsonToString( pJson, '/pProcessParameters'   );
pSourceDatabaseName  =                 JsonToString( pJson, '/pSourceDatabaseName'  );
pTargetDatabaseName  =                 JsonToString( pJson, '/pTargetDatabaseName'  );
# Numeric Parameters
pLogOutput           = StringToNumber( JsonToString( pJson, '/pLogOutput'           ) );
pStrictErrorHandling = StringToNumber( JsonToString( pJson, '/pStrictErrorHandling' ) );

### Get the parameters that differ from the default
pDiffer = JsonDiff( pDefaultParameters, pJson );
nSize = JsonSize( pDiffer );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  pDiffer = JsonReplace( pDiffer, '/'|NumberToString( nSize )|'/op', '"add"' );
END;
pJson = JsonPatch( '{}', pDiffer );

### LogOutput parameters
nSize = JsonSize( pJson );
WHILE( nSize > 0 );
  nSize = nSize - 1;
  sKey = JsonGetKey( pJson, nSize );
  pPassedParameters = JsonReplace( pPassedParameters, sKey, JsonGet( pJson, sKey ) );
END;

sMessages = JsonAdd( sMessages, '/Info/0', pPassedParameters );
IF( pLogOutput = 1 );
  LogOutput('INFO', JsonToString( sMessages, '/Info/0' ) );
ENDIF;

#EndRegion - Process Parameters
#################################################################################################

#################################################################################################
#Region - Validate Parameters

# Get Database Connection Details
sSourceDatabaseParameterType = JsonType( pSourceDatabaseName );
IF( sSourceDatabaseParameterType @<> 'object' );
  ExecuteProcess( '}bedrock-v12.session.start', 'pDatabaseName', pSourceDatabaseName, 'pJson', pJson ); sSourceConnectionDetails = sBedrockReturnValue;
ELSE;
  sSourceConnectionDetails = pSourceDatabaseName;
ENDIF;

#sTargetDatabaseParameterType = JsonType( pTargetDatabaseName );
#IF( sTargetDatabaseParameterType @<> 'object' );
#  ExecuteProcess( '}bedrock-v12.session.start', 'pDatabaseName', pTargetDatabaseName, 'pJson', pJson, 'pLogOutput', 1 ); sTargetConnectionDetails = sBedrockReturnValue;
#ELSE;
#  sTargetConnectionDetails = pTargetDatabaseName;
#ENDIF;

### If errors occurred terminate process with a major error status ###
IF( JsonSize( sMessages, '/Error' ) <> 0 );
    ProcessBreak;
ENDIF;

#EndRegion - Validate Parameters
#################################################################################################

#################################################################################################
#Region - Execute Process Remotely

# Get connection details
sSourceURL = JsonToString( sSourceConnectionDetails, '/sURL' );
sSourceSID = JsonToString( sSourceConnectionDetails, '/sSID' );

# Check if process exists on target

sURL = sSourceURL | '/Servers(''bedrock-5-dev'')/transactionlog';
sURL = 'https://us-east-1.planninganalytics.saas.ibm.com/prism/harmony/tiprocess/api/v1/Servers(''bedrock-5-dev'')/transactionlog';
sBody = '{
  "entryLimit":500,
  "skip":0,
  "fromTime":"2026-01-27T06:00:00.000Z",
  "toTime":"2026-01-29T06:59:59.000Z",
  "fieldMatch":"ALL",
  "orderby": "TimeStamp",
  "top":1,
  "filterFields":[
    {
      "name":"Cube",
      "operator":"EQUALS",
      "value":"Cube"
    }
  ]
}';

ExecuteProcess('}bedrock-v12.process.execute_http_request',
  'pMethod','POST',
  'pURL', sURL,
  'pBody', sBody,
  'pHeaders', '["Content-Type:application/json; charset=utf-8"]' );
sResponse = sBedrockReturnValue;
LogOutput( 'INFO', 'sResponse:'|sResponse );


